package org.codex.nfsugpreview;
import java.nio.*;import java.nio.file.*;
public class RoadHistoryTest{
 public static void main(String[] args)throws Exception{Path dir=Paths.get(args[0]);byte[] raw=Files.readAllBytes(dir.resolve("original-road-events.nrj"));NativeRoadHistory history=new NativeRoadHistory(raw);raw[0]=0;ByteBuffer reference=ByteBuffer.wrap(Files.readAllBytes(dir.resolve("road-history-reference.bin"))).order(ByteOrder.LITTLE_ENDIAN);int owners=reference.getInt(),checked=0;for(int i=0;i<owners;i++){reference.getInt();long end=reference.getLong();int page=reference.getInt(),count=reference.getInt();NativeRoadHistory.Samples samples=history.samples(history.epoch,end,page);int found=0;for(int cell=0;cell<38400;cell++)if(samples.event(cell)>=0)found++;if(found!=count)throw new AssertionError("Coverage count");for(int j=0;j<count;j++){int cell=reference.getInt();long ordinal=reference.getLong();long refresh=Integer.toUnsignedLong(reference.getInt());int offset=reference.getInt(),value=reference.getInt(),event=samples.event(cell);if(event<0||history.event(event).ordinal!=ordinal||history.event(event).refresh!=refresh||samples.offset(cell)!=offset||(history.event(event).texture().get(offset)&255)!=value)throw new AssertionError("Road source history mismatch");checked++;}}if(reference.hasRemaining())throw new AssertionError("Trailing reference");int rejected=0;for(int at:new int[]{0,8,16,24,32,40,48,56,64,72,80,88}){byte[] bad=Files.readAllBytes(dir.resolve("original-road-events.nrj"));ByteBuffer.wrap(bad).order(ByteOrder.LITTLE_ENDIAN).putLong(at,-1);try{new NativeRoadHistory(bad);throw new AssertionError("Accepted header "+at);}catch(IllegalArgumentException expected){rejected++;}}if(!history.event(0).texture().isReadOnly())throw new AssertionError("Mutable texture");System.out.println("PASS_ROAD_HISTORY owners="+owners+" events="+history.count()+" addresses="+checked+" malformed="+rejected);}
}
